-- Hoàn thiện bộ 3 ngữ cảnh cho N5 bài 7 (52 mục).

with classifications(word_jp,word_class,dictionary_form) as (values
 ('お茶','名詞','お茶'),('お酒','名詞','お酒'),('コーヒー','名詞','コーヒー'),('ご飯','名詞','ご飯'),
 ('ジュース','名詞','ジュース'),('たばこ','名詞','たばこ'),('チョコレート','名詞','チョコレート'),('パン','名詞','パン'),
 ('ビール','名詞','ビール'),('メール','名詞','メール'),('レポート','名詞','レポート'),('ワイン','名詞','ワイン'),
 ('卵','名詞','卵'),('手紙','名詞','手紙'),('果物','名詞','果物'),('水','名詞','水'),('牛肉','名詞','牛肉'),
 ('肉','名詞','肉'),('薬','名詞','薬'),('野菜','名詞','野菜'),('魚','名詞','魚'),('「写真を」撮る','動詞','撮る'),
 ('いつも','副詞','いつも'),('お正月','名詞','お正月'),('お花見','動名詞','お花見'),('カフェ','名詞','カフェ'),
 ('コメント','名詞','コメント'),('サッカー','名詞','サッカー'),('する','動詞','する'),('ちょっと','副詞','ちょっと'),
 ('テニス','名詞','テニス'),('みんなで','副詞','みんなで'),('レストラン','名詞','レストラン'),('一緒に','副詞','一緒に'),
 ('会う','動詞','会う'),('何','名詞','何'),('写真','名詞','写真'),('吸う','動詞','吸う'),('宿題','名詞','宿題'),
 ('店','名詞','店'),('庭','名詞','庭'),('映画','名詞','映画'),('時々','副詞','時々'),('書く','動詞','書く'),
 ('聞く','動詞','聞く'),('見る','動詞','見る'),('読む','動詞','読む'),('買う','動詞','買う'),('音楽','名詞','音楽'),
 ('食べる','動詞','食べる'),('食事する','動詞','食事する'),('飲む','動詞','飲む')
)
update public.jp_vocab v set word_class=c.word_class,dictionary_form=c.dictionary_form
from classifications c where v.level='N5' and v.lesson_no=7 and v.word_jp=c.word_jp;

-- Tách các câu đời thường bị dùng chung cho danh từ và động từ liên quan.
with fixes(word_jp,example_jp,example_vi,cloze_jp,answer,focus_note) as (values
 ('「写真を」撮る','旅行で家族の写真を撮りました。','Trong chuyến đi tôi đã chụp ảnh gia đình.','旅行で家族の写真を_____。','撮りました','写真を撮る là chụp ảnh.'),
 ('吸う','父は外でたばこを吸います。','Bố tôi hút thuốc ở bên ngoài.','父は外でたばこを_____。','吸います','たばこを吸う; nơi thực hiện đi với で.'),
 ('宿題','今日の宿題は少し難しいです。','Bài tập hôm nay hơi khó.','今日の_____は少し難しいです。','宿題','今日の + danh từ.'),
 ('書く','毎晩、短い日記を書いています。','Mỗi tối tôi viết một đoạn nhật ký ngắn.','毎晩、短い日記を_____います。','書いて','書く → 書いています.'),
 ('見る','週末に家族と映画を見ました。','Cuối tuần tôi đã xem phim cùng gia đình.','週末に家族と映画を_____。','見ました','見る → 見ました.'),
 ('買う','帰りにスーパーで牛乳を買います。','Trên đường về tôi mua sữa ở siêu thị.','帰りにスーパーで牛乳を_____。','買います','Nを買う; nơi mua đi với で.'),
 ('音楽','静かな音楽が好きです。','Tôi thích nhạc nhẹ.','静かな_____が好きです。','音楽','Đối tượng yêu thích đi với が.'),
 ('食べる','朝は果物を食べています。','Buổi sáng tôi ăn trái cây.','朝は果物を_____います。','食べて','食べる → 食べています.'),
 ('食事する','今夜、家族と食事します。','Tối nay tôi dùng bữa cùng gia đình.','今夜、家族と_____。','食事します','Người cùng ăn đi với と.'),
 ('飲む','暑い日は水をたくさん飲みます。','Ngày nóng tôi uống nhiều nước.','暑い日は水をたくさん_____。','飲みます','Nを飲む.')
)
update public.jp_vocab_examples e set example_jp=f.example_jp,example_vi=f.example_vi,
 cloze_jp=f.cloze_jp,answer=f.answer,difficulty=1,focus_note=f.focus_note
from fixes f join public.jp_vocab v on v.level='N5' and v.lesson_no=7 and v.word_jp=f.word_jp
where e.vocab_id=v.id and e.example_no=2;

with curated(word_jp,example_no,example_type,example_jp,example_vi,cloze_jp,answer,difficulty,focus_note) as (values
 ('お茶',1,'exam','食事の後で温かいお茶を飲みました。','Sau bữa ăn tôi đã uống trà nóng.','食事の後で温かい_____を飲みました。','お茶',1,'Đồ uống đi với を飲む.'),
 ('お茶',3,'business','お客様にお茶をお出ししてください。','Vui lòng mời trà khách.','お客様に_____をお出ししてください。','お茶',2,'お茶をお出しする là mời trà lịch sự.'),
 ('お酒',1,'exam','父はお酒をあまり飲みません。','Bố tôi không uống nhiều rượu.','父は_____をあまり飲みません。','お酒',1,'あまり đi với phủ định.'),
 ('お酒',3,'business','勤務中はお酒を飲んではいけません。','Không được uống rượu trong giờ làm việc.','勤務中は_____を飲んではいけません。','お酒',2,'Vてはいけません chỉ cấm đoán.'),
 ('コーヒー',1,'exam','眠かったので、濃いコーヒーを飲みました。','Vì buồn ngủ nên tôi uống cà phê đậm.','眠かったので、濃い_____を飲みました。','コーヒー',1,'濃いコーヒー là cà phê đậm.'),
 ('コーヒー',3,'business','会議室にコーヒーを十杯用意しました。','Tôi đã chuẩn bị mười cốc cà phê trong phòng họp.','会議室に_____を十杯用意しました。','コーヒー',2,'Đếm cốc dùng 杯.'),
 ('ご飯',1,'exam','母が作ったご飯はとてもおいしかったです。','Cơm mẹ nấu rất ngon.','母が作った_____はとてもおいしかったです。','ご飯',1,'Mệnh đề bổ nghĩa cho ご飯.'),
 ('ご飯',3,'business','昼の会議前に早めにご飯を食べました。','Tôi đã ăn sớm trước cuộc họp trưa.','昼の会議前に早めに_____を食べました。','ご飯',2,'ご飯を食べる.'),
 ('ジュース',1,'exam','冷蔵庫にりんごジュースが一本あります。','Trong tủ lạnh có một chai nước táo.','冷蔵庫にりんご_____が一本あります。','ジュース',1,'Loại quả + ジュース.'),
 ('ジュース',3,'business','休憩室のジュースは自由に飲めます。','Nước trái cây trong phòng nghỉ có thể uống tự do.','休憩室の_____は自由に飲めます。','ジュース',2,'Nは自由にV được dùng trong hướng dẫn.'),
 ('たばこ',1,'exam','この建物の中ではたばこを吸えません。','Trong tòa nhà này không thể hút thuốc.','この建物の中では_____を吸えません。','たばこ',1,'たばこを吸う.'),
 ('たばこ',3,'business','たばこは指定された場所でお願いします。','Vui lòng chỉ hút thuốc ở nơi quy định.','_____は指定された場所でお願いします。','たばこ',2,'Cách nhắc lịch sự về khu vực hút thuốc.'),
 ('チョコレート',1,'exam','妹にチョコレートを一箱あげました。','Tôi đã cho em gái một hộp sô-cô-la.','妹に_____を一箱あげました。','チョコレート',1,'Đếm hộp dùng 箱.'),
 ('チョコレート',3,'business','受付にお土産のチョコレートを置きました。','Tôi đã để sô-cô-la quà tặng ở quầy lễ tân.','受付にお土産の_____を置きました。','チョコレート',2,'お土産の + món quà.'),
 ('パン',1,'exam','駅の近くの店で焼きたてのパンを買いました。','Tôi mua bánh mì mới nướng ở tiệm gần ga.','駅の近くの店で焼きたての_____を買いました。','パン',1,'焼きたてのパン là bánh mì mới nướng.'),
 ('パン',3,'business','朝の研修用にパンを人数分注文しました。','Tôi đã đặt đủ bánh mì theo số người cho buổi đào tạo sáng.','朝の研修用に_____を人数分注文しました。','パン',2,'人数分 là phần đủ theo số người.'),
 ('ビール',1,'exam','暑い日に冷たいビールを飲みました。','Tôi đã uống bia lạnh vào ngày nóng.','暑い日に冷たい_____を飲みました。','ビール',1,'冷たい bổ nghĩa cho đồ uống.'),
 ('ビール',3,'business','懇親会のためにビールを用意しました。','Tôi đã chuẩn bị bia cho buổi giao lưu.','懇親会のために_____を用意しました。','ビール',2,'Nのために用意する.'),
 ('メール',1,'exam','先生から届いたメールを読みました。','Tôi đã đọc email nhận được từ giáo viên.','先生から届いた_____を読みました。','メール',1,'Người gửi đi với から.'),
 ('メール',3,'business','添付資料を確認してからメールを返信します。','Tôi sẽ kiểm tra tài liệu đính kèm rồi trả lời email.','添付資料を確認してから_____を返信します。','メール',2,'メールを返信する.'),
 ('レポート',1,'exam','来週までに環境についてのレポートを出します。','Tôi sẽ nộp báo cáo về môi trường trước tuần sau.','来週までに環境についての_____を出します。','レポート',2,'Nについてのレポート.'),
 ('レポート',3,'business','不具合の原因をレポートにまとめました。','Tôi đã tổng hợp nguyên nhân lỗi vào báo cáo.','不具合の原因を_____にまとめました。','レポート',2,'Nをレポートにまとめる.'),
